Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "name": "dataset"
  },
  "padding": {
    "left": 0,
    "right": 2,
    "top": 16,
    "bottom": 2
  },
  "transform": [
    {
      "calculate": "format(datum[''Growth''], ''+.1%'')",
      "as": "growth_text"
    },
    {
      "window": [
        {
          "op": "row_number",
          "as": "row_number"
        }
      ]
    },
    {
      "joinaggregate": [
        {
          "op": "valid",
          "field": "Growth before",
          "as": "ticks"
        }
      ]
    },
    {
      "calculate": "datum[''row_number''] == 1 ? ''National '' + format(datum[''National''], ''+.1%'') : ''''",
      "as": "national_text"
    },
    {
      "calculate": "isValid(datum[''Growth before'']) ? ((isValid(datum[''Growth before'']) && datum[''Growth''] >= datum[''Growth before'']) ? ''▲ '' : ''▼ '') + format(abs(datum[''Growth''] - datum[''Growth before'']) * 100, ''.1f'') + '' pts'' : ''''",
      "as": "change_text"
    },
    {
      "calculate": "max(0, datum[''Growth''], isValid(datum[''Growth before'']) ? datum[''Growth before''] : 0)",
      "as": "label_x"
    },
    {
      "calculate": "format(datum[''Growth''], ''+.1%'')",
      "as": "Growth, this year"
    },
    {
      "calculate": "isValid(datum[''Growth before'']) ? format(datum[''Growth before''], ''+.1%'') : ''not shown''",
      "as": "Growth, a year before"
    },
    {
      "calculate": "isValid(datum[''Growth before'']) ? (((isValid(datum[''Growth before'']) && datum[''Growth''] >= datum[''Growth before'']) ? ''faster by '' : ''slower by '') + format(abs(datum[''Growth''] - datum[''Growth before'']) * 100, ''.1f'') + '' points'') : ''''",
      "as": "Change"
    },
    {
      "calculate": "format(datum[''Spent now''], '',.2f'') + '' bn SAR''",
      "as": "Spent, same weeks"
    },
    {
      "calculate": "format(datum[''Spent before''], '',.2f'') + '' bn SAR''",
      "as": "Same weeks, a year before"
    }
  ],
  "encoding": {
    "y": {
      "field": "City",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "Growth",
        "order": "descending"
      },
      "scale": {
        "paddingInner": 0.45,
        "paddingOuter": 0.25
      },
      "axis": {
        "domain": false,
        "ticks": false,
        "labelPadding": 8,
        "labelFontSize": 12,
        "labelColor": "#4F5966"
      }
    },
    "tooltip": [
      {
        "field": "City"
      },
      {
        "field": "Growth, this year"
      },
      {
        "field": "Growth, a year before"
      },
      {
        "field": "Change"
      },
      {
        "field": "Spent, same weeks"
      },
      {
        "field": "Same weeks, a year before"
      }
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "cornerRadiusEnd": 2
      },
      "encoding": {
        "x": {
          "field": "Growth",
          "type": "quantitative",
          "axis": null,
          "scale": {
            "zero": true,
            "nice": false
          }
        },
        "color": {
          "condition": [
            {
              "test": "isValid(datum[''Growth before'']) && datum[''Growth''] >= datum[''Growth before'']",
              "value": "#16A34A"
            },
            {
              "test": "isValid(datum[''Growth before''])",
              "value": "#C81E1E"
            }
          ],
          "value": "#D0D5DD"
        }
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#344054"
      },
      "encoding": {
        "x": {
          "field": "Growth before",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "rule",
        "color": "#4F5966",
        "strokeDash": [
          3,
          3
        ],
        "strokeWidth": 1
      },
      "encoding": {
        "x": {
          "field": "National",
          "type": "quantitative"
        },
        "y": {
          "value": 0
        },
        "y2": {
          "value": "height"
        },
        "opacity": {
          "condition": {
            "test": "datum[''row_number''] == 1",
            "value": 1
          },
          "value": 0
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "center",
        "baseline": "bottom",
        "dy": -3,
        "fontSize": 11,
        "color": "#4F5966"
      },
      "encoding": {
        "x": {
          "field": "National",
          "type": "quantitative"
        },
        "y": {
          "value": 0
        },
        "text": {
          "field": "national_text"
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "rect",
        "color": "#FFFFFF",
        "xOffset": 3,
        "x2Offset": 112
      },
      "encoding": {
        "x": {
          "field": "label_x",
          "type": "quantitative"
        },
        "x2": {
          "field": "label_x"
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 6,
        "fontSize": 12,
        "color": "#13161B"
      },
      "encoding": {
        "x": {
          "field": "label_x",
          "type": "quantitative"
        },
        "text": {
          "field": "growth_text"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": 52,
        "fontSize": 11,
        "fontWeight": 600
      },
      "encoding": {
        "x": {
          "field": "label_x",
          "type": "quantitative"
        },
        "text": {
          "field": "change_text"
        },
        "color": {
          "condition": {
            "test": "isValid(datum[''Growth before'']) && datum[''Growth''] >= datum[''Growth before'']",
            "value": "#15803D"
          },
          "value": "#C81E1E"
        }
      }
    },
    {
      "data": {
        "values": [
          {}
        ]
      },
      "mark": {
        "type": "rule",
        "color": "#4F5966"
      },
      "encoding": {
        "x": {
          "datum": 0
        },
        "y": {
          "value": 0
        },
        "y2": {
          "value": "height"
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "dy": 10,
        "fontSize": 11,
        "fontWeight": 600,
        "color": "#15803D"
      },
      "encoding": {
        "x": {
          "value": 0
        },
        "y": {
          "value": "height"
        },
        "tooltip": null,
        "text": {
          "value": {
            "expr": "datum[''row_number''] == 1 && datum[''ticks''] > 0 ? ''▲ Faster than a year before'' : ''''"
          }
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "top",
        "dy": 10,
        "dx": 152,
        "fontSize": 11,
        "fontWeight": 600,
        "color": "#C81E1E"
      },
      "encoding": {
        "x": {
          "value": 0
        },
        "y": {
          "value": "height"
        },
        "tooltip": null,
        "text": {
          "value": {
            "expr": "datum[''row_number''] == 1 && datum[''ticks''] > 0 ? ''▼ Slower'' : ''''"
          }
        }
      }
    }
  ]
}'
